// --- File: ui/SplashScreen.js ---
// --- ui\SplashScreen.js ---
window.SF = window.SF || {};

SF.SplashScreen = class SplashScreen {
    constructor() {
        this.container = null;
        this.styleElement = null;
        this.cssText = `
            #sf-splash-screen {
                position: fixed;
                top: 0; left: 0; width: 100vw; height: 100vh;
                background: radial-gradient(circle at center, #0d1117 0%, #000000 100%);
                z-index: 2147483647;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                font-family: 'Tajawal', 'Cairo', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                direction: rtl;
                opacity: 1;
            }

            #sf-splash-screen.sf-fading-out {
                transition: opacity 0.8s ease-in-out;
                opacity: 0;
            }

            .sf-splash-glass {
                background: rgba(255, 255, 255, 0.03);
                border: 1px solid rgba(255, 255, 255, 0.1);
                box-shadow: 0 0 40px rgba(52, 152, 219, 0.2), inset 0 0 20px rgba(255, 255, 255, 0.02);
                border-radius: 20px;
                padding: 40px 60px;
                text-align: center;
                transform: translateY(30px) scale(0.95);
                opacity: 0;
                animation: sf-slide-up 1s cubic-bezier(0.16, 1, 0.3, 1) 0.2s forwards;
            }

            @keyframes sf-slide-up {
                to { transform: translateY(0) scale(1); opacity: 1; }
            }

            .sf-splash-logo {
                font-size: 65px;
                filter: drop-shadow(0 0 15px rgba(241, 196, 15, 0.6));
                animation: sf-bounce 2s infinite alternate ease-in-out;
                display: flex;
                gap: 20px;
                justify-content: center;
                margin-bottom: 10px;
            }

            .sf-splash-logo span {
                display: inline-block;
                animation: sf-float 3s infinite ease-in-out;
            }
            
            .sf-splash-logo span:nth-child(2) { animation-delay: 0.5s; }
            .sf-splash-logo span:nth-child(3) { animation-delay: 1s; }

            @keyframes sf-bounce {
                0% { filter: drop-shadow(0 0 15px rgba(241, 196, 15, 0.4)); }
                100% { filter: drop-shadow(0 0 35px rgba(241, 196, 15, 1)); }
            }

            @keyframes sf-float {
                0%, 100% { transform: translateY(0); }
                50% { transform: translateY(-15px) scale(1.1); }
            }

            .sf-splash-title {
                color: #fff;
                font-size: 32px;
                font-weight: 800;
                margin-top: 20px;
                letter-spacing: 2px;
                text-transform: uppercase;
                text-shadow: 0 0 20px rgba(52, 152, 219, 0.8);
                background: linear-gradient(90deg, #3498db, #2ecc71, #3498db);
                background-size: 200% auto;
                color: transparent;
                -webkit-background-clip: text;
                animation: sf-shine 3s linear infinite;
            }

            @keyframes sf-shine {
                to { background-position: 200% center; }
            }

            .sf-splash-subtitle {
                color: #f1c40f;
                font-size: 16px;
                margin-top: 15px;
                letter-spacing: 0px;
                font-weight: bold;
                text-shadow: 0 0 10px rgba(241, 196, 15, 0.5);
            }

            .sf-progress-bar {
                width: 100%;
                height: 4px;
                background: rgba(255, 255, 255, 0.1);
                border-radius: 2px;
                margin-top: 30px;
                overflow: hidden;
                position: relative;
            }

            .sf-progress-fill {
                height: 100%;
                width: 0%;
                background: #3498db;
                box-shadow: 0 0 10px #3498db;
                border-radius: 2px;
                animation: sf-fill 2.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
            }

            @keyframes sf-fill {
                0% { width: 0%; }
                40% { width: 60%; }
                80% { width: 90%; }
                100% { width: 100%; }
            }
        `;
    }

    injectCSS() {
        this.styleElement = document.createElement('style');
        this.styleElement.textContent = this.cssText;
        document.head.appendChild(this.styleElement);
    }

    createUI() {
        this.container = document.createElement('div');
        this.container.id = 'sf-splash-screen';
        
        // رسم الشعار كـ SVG معقد يعطي إيحاء الذكاء الاصطناعي والمزرعة
        this.container.innerHTML = `
            <div class="sf-splash-glass">
                <div class="sf-splash-logo">
                    <span>🐮</span>
                    <span>🌾</span>
                    <span>🚜</span>
                </div>
                <div class="sf-splash-title">حصاد مظبوط</div>
                <div class="sf-splash-subtitle">هيثم كوتش يُرحب بكم في نظام المزرعة الذكي ✨</div>
                <div class="sf-progress-bar">
                    <div class="sf-progress-fill"></div>
                </div>
            </div>
        `;
        document.body.appendChild(this.container);
    }

    show(callback) {
        this.injectCSS();
        this.createUI();

        // ✅ 4 ثواني ثابتة — كافية لتغطي تحميل اللعبة دون إخفاء القطة لفترة طويلة
        setTimeout(() => {
            if (!this.container) return;
            this.container.classList.add('sf-fading-out');
            setTimeout(() => {
                this.destroy();
                if (callback && typeof callback === 'function') callback();
            }, 800);
        }, 4000);
    }

    destroy() {
        if (this.container && this.container.parentNode) {
            this.container.parentNode.removeChild(this.container);
        }
        if (this.styleElement && this.styleElement.parentNode) {
            this.styleElement.parentNode.removeChild(this.styleElement);
        }
        // تفريغ الذاكرة (Garbage Collection)
        this.container = null;
        this.styleElement = null;
    }
};


// --- File: ui/UIManager.js ---
// --- ui\UIManager.js ---
window.SF = window.SF || {};

// ── نظام الأدمن السري ──────────────────────────────────────────
SF._AdminGuard = {
    SECRET:    'sf-dev-2025',
    _unlocked: false,
    _buffer:   '',
    _STORE_KEY: 'SF_AdminUnlocked',

    init() {
        this._unlocked = sessionStorage.getItem(this._STORE_KEY) === '1';
        document.addEventListener('keydown', (e) => this._onKey(e));
    },

    isUnlocked() { return this._unlocked; },

    _onKey(e) {
        if (['INPUT','TEXTAREA'].includes(e.target.tagName)) return;
        this._buffer += e.key.toLowerCase();
        if (this._buffer.length > this.SECRET.length + 5)
            this._buffer = this._buffer.slice(-this.SECRET.length - 5);
        if (this._buffer.includes(this.SECRET)) {
            this._buffer = '';
            this._toggle();
        }
    },

    _toggle() {
        this._unlocked = !this._unlocked;
        sessionStorage.setItem(this._STORE_KEY, this._unlocked ? '1' : '0');
        if (window.SF && window.SF.ui) window.SF.ui._refreshAdminTabs();
        this._toast(this._unlocked ? '🔓 وضع الأدمن مفعَّل' : '🔒 وضع الأدمن مُغلق');
    },

    _toast(msg) {
        const t = document.createElement('div');
        t.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#1a1a2e;color:#e74c3c;border:1px solid #e74c3c;padding:8px 20px;border-radius:20px;font-weight:bold;font-size:13px;z-index:999999;pointer-events:none;';
        t.textContent = msg;
        document.body.appendChild(t);
        setTimeout(() => t.remove(), 2500);
    }
};
SF.UIManager = class UIManager {
    constructor() {
        this.app = null;
        this.contentArea = null;
        this.topBar = null;

        this.injectCSS();
        this.createLayout();
        // تهيئة نظام الأدمن
        SF._AdminGuard.init();


        // Add modules that were already registered before UI was ready
        SF.modules.getModules().forEach(mod => this.addModuleTab(mod));

        // Select first tab by default
        const firstMod = SF.modules.getModules()[0];
        if (firstMod) {
            this.switchTab(firstMod.id);
            // Hide panel initially so it doesn't clutter the screen
            this.app.classList.add('sf-hidden');
        }
    }

    injectCSS() {
        const style = document.createElement('style');
        style.textContent = SF.Styles;
        document.head.appendChild(style);
    }

    createLayout() {
        // 1. Fixed Top Bar (Holds the main button and dropdown)
        this.topBar = document.createElement('div');
        this.topBar.id = 'sf-top-bar';

        this.mainMenuBtn = document.createElement('div');
        this.mainMenuBtn.className = 'sf-menu-btn';
        this.mainMenuBtn.innerHTML = '🌾 أدوات SupremeFarm ⬇️';

        this.dropdownMenu = document.createElement('div');
        this.dropdownMenu.className = 'sf-dropdown-menu sf-hidden';

        this.mainMenuBtn.onclick = () => {
            this.dropdownMenu.classList.toggle('sf-hidden');
        };

        this.topBar.appendChild(this.mainMenuBtn);
        this.topBar.appendChild(this.dropdownMenu);
        document.body.appendChild(this.topBar);

        // 2. Main App Panel (Fixed Center Modal)
        this.app = document.createElement('div');
        this.app.id = 'sf-app';

        // Header of the Panel
        const header = document.createElement('div');
        header.className = 'sf-header';

        this.titleEl = document.createElement('div');
        this.titleEl.className = 'sf-title';
        this.titleEl.innerHTML = `🌾 Supreme Farm`;

        const controls = document.createElement('div');
        controls.className = 'sf-controls';

        const closeBtn = document.createElement('button');
        closeBtn.innerHTML = 'إغلاق النافذة ✖';
        closeBtn.onclick = () => {
            this.app.classList.add('sf-hidden');
            // Remove active state from top buttons
            this.topBar.querySelectorAll('.sf-tab').forEach(t => t.classList.remove('active'));
        };

        controls.appendChild(closeBtn);
        header.appendChild(this.titleEl);
        header.appendChild(controls);

        // Content Area
        this.contentArea = document.createElement('div');
        this.contentArea.className = 'sf-content';

        this.app.appendChild(header);
        this.app.appendChild(this.contentArea);
        document.body.appendChild(this.app);
    }

    addModuleTab(mod) {
        if (!this.topBar) return;

        // Tab Button (Inside dropdown)
        const tab = document.createElement('div');
        tab.className = 'sf-tab';
        tab.id = `tab-${mod.id}`;
        tab.innerHTML = `${mod.icon} <span>${mod.name}</span>`;
        tab.onclick = () => {
            // If already active and panel is open, close it
            if (tab.classList.contains('active') && !this.app.classList.contains('sf-hidden')) {
                this.app.classList.add('sf-hidden');
                tab.classList.remove('active');
            } else {
                this.switchTab(mod.id);
            }
            this.dropdownMenu.classList.add('sf-hidden');
        };

        this.dropdownMenu.appendChild(tab);

        // Module Container inside Panel
        const modContainer = document.createElement('div');
        modContainer.className = 'sf-module';
        modContainer.id = `mod-${mod.id}`;
        this.contentArea.appendChild(modContainer);

        // Initialize module HTML
        mod.init(modContainer);
    }

    _refreshAdminTabs() {
        // إعادة بناء تبويبات الأدمن عند تغيير حالة القفل
        SF.modules.getModules().filter(m => m.adminOnly).forEach(mod => {
            const existingTab = this.topBar.querySelector(`#tab-${mod.id}`);
            if (SF._AdminGuard.isUnlocked() && !existingTab) {
                // ظهر Tab جديد
                const tab = document.createElement('div');
                tab.className = 'sf-tab sf-tab-admin';
                tab.id = `tab-${mod.id}`;
                tab.innerHTML = `${mod.icon} <span>${mod.name}</span> <span style="font-size:9px;color:#e74c3c;margin-right:3px">🔴</span>`;
                tab.onclick = () => {
                    if (tab.classList.contains('active') && !this.app.classList.contains('sf-hidden')) {
                        this.app.classList.add('sf-hidden');
                        tab.classList.remove('active');
                    } else { this.switchTab(mod.id); }
                    this.dropdownMenu.classList.add('sf-hidden');
                };
                this.dropdownMenu.appendChild(tab);
                // إظهار الـ container
                const mc = this.contentArea.querySelector(`#mod-${mod.id}`);
                if (mc) mc.style.display = '';
            } else if (!SF._AdminGuard.isUnlocked() && existingTab) {
                // إخفاء Tab
                existingTab.remove();
                const mc = this.contentArea.querySelector(`#mod-${mod.id}`);
                if (mc) mc.style.display = 'none';
            }
        });
    }

    switchTab(moduleId) {
        const tabs = this.topBar.querySelectorAll('.sf-tab');
        const mods = this.app.querySelectorAll('.sf-module');

        let activeMod = null;

        tabs.forEach(tab => {
            if (tab.id === `tab-${moduleId}`) tab.classList.add('active');
            else tab.classList.remove('active');
        });

        mods.forEach(mod => {
            if (mod.id === `mod-${moduleId}`) {
                mod.classList.add('active');
                activeMod = SF.modules.getModules().find(x => x.id === moduleId);
                if (activeMod && activeMod.update) activeMod.update();
            } else {
                mod.classList.remove('active');
            }
        });

        // Open the panel
        this.app.classList.remove('sf-hidden');
        if (activeMod) {
            this.titleEl.innerHTML = `${activeMod.icon} ${activeMod.name}`;
        }
    }
};





