                        sysLog('تم اعتراض حصاد الآلة (الوضع: ' + modeName + '). إرسال طلبات حصاد يدوية لمنع خصم البنزين.');
                        closeCropinator(gw.ControllerConst ? gw.ControllerConst.Cropinator : 10010);

