    const imgCache = (uw.__SF_IMG_CACHE = uw.__SF_IMG_CACHE || {});

    function showToast(msg, type = "success") {
        const t = document.createElement("div");
        t.style.cssText = "position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:9999999;padding:10px 22px;border-radius:10px;font-weight:bold;font-family:'Alexandria',Tahoma,sans-serif;box-shadow:0 6px 20px rgba(0,0,0,0.35);font-size:13px;pointer-events:none;transition:opacity 0.3s;" + 
            (type === "error" ? "background:#b71c1c;color:#fff;" : "background:#2e7d32;color:#fff;");
        t.innerText = msg;
        (document.body || document.documentElement).appendChild(t);
        setTimeout(() => {
            t.style.opacity = "0";
            setTimeout(() => t.remove(), 300);
        }, 2500);
    }

